-- Generated by tools/dim/import_scans.py. 9 image-only questions: Kimya test toplusu I (2025), bölmə 6.
-- Run once in Supabase SQL Editor. Safe to re-run: the topic is created only if missing, questions are upserted by code.
-- Upload the images (out/upload_kitab/*.webp) to the question-images bucket too.
set standard_conforming_strings = on;
begin;

do $$
begin
  if not exists (select 1 from subjects where slug = 'kimya') then
    raise exception 'subjects cədvəlində slug=kimya yoxdur';
  end if;
  if not exists (select 1 from pg_enum e join pg_type t on t.oid = e.enumtypid
                  where t.typname = 'exam_level' and e.enumlabel = 'qebul') then
    raise exception 'exam_level enum-unda qebul etiketi yoxdur: import dayandırıldı';
  end if;
  if not exists (select 1 from pg_enum e join pg_type t on t.oid = e.enumtypid
                  where t.typname = 'question_type' and e.enumlabel = 'aciq_eded') then
    raise exception 'question_type enum-unda aciq_eded etiketi yoxdur: import dayandırıldı';
  end if;
  if (select count(*) from pg_enum e join pg_type t on t.oid = e.enumtypid
       where t.typname = 'question_type' and e.enumlabel in ('aciq_eded', 'coxlu_secim', 'uygunlasdirma')) <> 3 then
    raise exception 'question_type enum-unda lazımi etiketlər yoxdur (migration 014?): import dayandırıldı';
  end if;
end $$;

-- section and topic (only if missing)
insert into topics (subject_id, parent_id, name, sort_order)
select s.id, null, 'Ümumi kimya', 50 from subjects s where s.slug = 'kimya'
on conflict (subject_id, parent_id, name) do nothing;

insert into topics (subject_id, parent_id, name, sort_order)
select s.id, p.id, 'Maddə miqdarı. Avoqadro qanunu', 50
  from subjects s join topics p on p.subject_id = s.id and p.parent_id is null and p.name = 'Ümumi kimya'
 where s.slug = 'kimya'
on conflict (subject_id, parent_id, name) do nothing;

insert into questions (code, topic_id, type, body, image_path, options, correct_answer, difficulty, solution,
                       exam_levels, groups, year, source, source_ref, is_active)
select v.code, t.id, v.type::question_type, '', v.image_path, v.options::jsonb, v.correct,
       3::smallint, null, array['qebul']::exam_level[], '{}'::smallint[], 2025::smallint, 'DİM',
       'Kimya test toplusu I (2025), bölmə 6' || ', sual ' || (regexp_match(v.code, 'Q(\d+)$'))[1]::int, true
  from (values
  ('KT1-S06-Q047', 'KT1-S06-Q047.webp', '24', 'coxlu_secim', null),
  ('KT1-S06-Q048', 'KT1-S06-Q048.webp', '245', 'coxlu_secim', null),
  ('KT1-S06-Q049', 'KT1-S06-Q049.webp', '13', 'coxlu_secim', null),
  ('KT1-S06-Q050', 'KT1-S06-Q050.webp', '56', 'coxlu_secim', null),
  ('KT1-S06-Q051', 'KT1-S06-Q051.webp', '44,8', 'aciq_eded', null),
  ('KT1-S06-Q052', 'KT1-S06-Q052.webp', '20', 'aciq_eded', null),
  ('KT1-S06-Q053', 'KT1-S06-Q053.webp', '10', 'aciq_eded', null),
  ('KT1-S06-Q054', 'KT1-S06-Q054.webp', 'A;E;D', 'uygunlasdirma', '{"1": "ABCDE", "2": "ABCDE", "3": "ABCDE"}'),
  ('KT1-S06-Q055', 'KT1-S06-Q055.webp', 'E;A;BC', 'uygunlasdirma', '{"1": "ABCDE", "2": "ABCDE", "3": "ABCDE"}')
       ) as v(code, image_path, correct, type, options)
  join subjects s on s.slug = 'kimya'
  join topics sec on sec.subject_id = s.id and sec.parent_id is null and sec.name = 'Ümumi kimya'
  join topics t on t.subject_id = s.id and t.parent_id = sec.id and t.name = 'Maddə miqdarı. Avoqadro qanunu'
on conflict (code) do update set
  topic_id = excluded.topic_id, type = excluded.type, image_path = excluded.image_path, options = excluded.options,
  correct_answer = excluded.correct_answer, source_ref = excluded.source_ref, is_active = excluded.is_active;

do $$
declare n integer;
begin
  select count(*) into n from questions where code in ('KT1-S06-Q047', 'KT1-S06-Q048', 'KT1-S06-Q049', 'KT1-S06-Q050', 'KT1-S06-Q051', 'KT1-S06-Q052', 'KT1-S06-Q053', 'KT1-S06-Q054', 'KT1-S06-Q055');
  if n <> 9 then
    raise exception 'Gözlənilən 9 sual, bazada % tapıldı: geri alınır', n;
  end if;
end $$;

commit;

select count(*) as yuklenen_sual from questions where code like 'KT1-S06-%';
